[CmdletBinding()]
param([ValidateSet('LandPortal_Dev','LandPortal_Test')][string]$Database='LandPortal_Dev', [string]$Output='.local/evidence/phase2a/before-dev.json', [string]$CompareTo)
. (Join-Path $PSScriptRoot 'common.ps1')
$conn = New-Object System.Data.SqlClient.SqlConnection (Get-ProjectConnectionBuilder $Database).ConnectionString
function Rows([string]$sql) {
    $cmd=$conn.CreateCommand(); $cmd.CommandText=$sql; $reader=$cmd.ExecuteReader(); $rows=New-Object System.Collections.Generic.List[object]
    try { while($reader.Read()) { $row=[ordered]@{}; for($i=0;$i -lt $reader.FieldCount;$i++) { $value=$reader.GetValue($i); if($value -is [DBNull]) {$value=$null} elseif($value -is [byte[]]) {$value=[Convert]::ToBase64String($value)} elseif($value -is [DateTimeOffset]) {$value=$value.ToString('O')} elseif($value -is [DateTime]) {$value=$value.ToString('O')} elseif($value -is [Guid]) {$value=$value.ToString()} $row[$reader.GetName($i)]=$value }; $rows.Add([pscustomobject]$row) } } finally {$reader.Dispose();$cmd.Dispose()}; return ,$rows.ToArray()
}
function HashText([string]$value) { $sha=[Security.Cryptography.SHA256]::Create();try {return ([BitConverter]::ToString($sha.ComputeHash([Text.Encoding]::UTF8.GetBytes($value)))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()} }
function LocalRoot([string]$key) { $path=[Environment]::GetEnvironmentVariable($key,'Process');if([string]::IsNullOrWhiteSpace($path)){throw "Missing $key"};if(-not [IO.Path]::IsPathRooted($path)){$path=Join-Path $script:ProjectRoot $path}; $full=[IO.Path]::GetFullPath($path);$prefix=[IO.Path]::GetFullPath((Join-Path $script:ProjectRoot '.local'))+[IO.Path]::DirectorySeparatorChar;if(-not $full.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Preservation roots must remain in the project .local directory.'};return $full }
function FileEntry([string]$root,[string]$key,[string]$expected) { $path=[IO.Path]::GetFullPath((Join-Path $root $key));if(-not $path.StartsWith($root.TrimEnd('\')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Unsafe storage key.'};$exists=Test-Path -LiteralPath $path -PathType Leaf;$hash=if($exists){(Get-FileHash -LiteralPath $path -Algorithm SHA256).Hash.ToLowerInvariant()}else{$null};return [ordered]@{key=$key;exists=$exists;sha256=$hash;expectedSha256=$expected;matches=($exists -and $hash -ceq $expected);bytes=if($exists){(Get-Item -LiteralPath $path).Length}else{$null}} }
try {
    $conn.Open(); $target=Rows 'SELECT DB_NAME() AS DatabaseName, CAST(SERVERPROPERTY(''MachineName'') AS nvarchar(200)) AS MachineName, compatibility_level AS Compatibility FROM sys.databases WHERE name=DB_NAME()'
    if($target[0].DatabaseName -cne $Database -or $target[0].MachineName -ine $env:COMPUTERNAME){throw 'Preservation target must be the named local project database.'}
    $groups=[ordered]@{}
    $groups.identities=Rows 'SELECT s.Id,s.Source,s.Kind,s.SourceId,s.ContentId,s.CanonicalUrl,s.LastContentHash FROM SourceRecords s WHERE s.Source=N''qldd.mae.gov.vn'' ORDER BY s.Kind,s.SourceId'
    $groups.publicPayload=Rows 'SELECT c.Id,c.Kind,c.PrimaryCategoryId,c.PublishedRevisionId,c.PublishedAtUtc,c.SourcePublishedDate,c.OriginalDateText,c.DatePrecision,r.Title,r.Summary,r.Author,r.SourceCredit,r.BodyHtml,r.ContentHash FROM Contents c JOIN SourceRecords s ON s.ContentId=c.Id LEFT JOIN Revisions r ON r.Id=c.PublishedRevisionId WHERE s.Source=N''qldd.mae.gov.vn'' ORDER BY c.Id'
    $groups.sourceRevisions=Rows 'SELECT r.Id,r.ContentId,r.Title,r.Summary,r.Author,r.SourceCredit,r.BodyHtml,r.ContentHash,r.IsSourceRevision FROM Revisions r JOIN SourceRecords s ON s.ContentId=r.ContentId WHERE s.Source=N''qldd.mae.gov.vn'' AND r.IsSourceRevision=1 ORDER BY r.ContentId,r.Id'
    $groups.categories=Rows 'SELECT Id,Name,Slug,SourceUrl,SortOrder,ParentId FROM Categories ORDER BY Id'
    $groups.categoryMappings=Rows 'SELECT cc.ContentId,cc.CategoryId FROM ContentCategories cc JOIN SourceRecords s ON s.ContentId=cc.ContentId WHERE s.Source=N''qldd.mae.gov.vn'' ORDER BY cc.ContentId,cc.CategoryId'
    $groups.aliases=Rows 'SELECT a.Id,a.ContentId,a.Url,a.UrlHash FROM SourceUrlAliases a JOIN SourceRecords s ON s.ContentId=a.ContentId WHERE s.Source=N''qldd.mae.gov.vn'' ORDER BY a.Id'
    $groups.media=Rows 'SELECT Id,Sha256,StorageKey,MimeType,ByteLength,SourceUrl,OriginalName,Width,Height,ScanStatus,IsQuarantined FROM MediaAssets WHERE SourceUrl<>N'''' ORDER BY Id'
    $groups.assetMappings=Rows 'SELECT ca.RevisionId,ca.MediaAssetId,ca.Usage,ca.Caption,ca.SortOrder FROM ContentAssets ca JOIN Revisions r ON r.Id=ca.RevisionId JOIN SourceRecords s ON s.ContentId=r.ContentId WHERE s.Source=N''qldd.mae.gov.vn'' ORDER BY ca.RevisionId,ca.MediaAssetId'
    $groups.snapshots=Rows 'SELECT Id,CrawlRunId,SourceUrl,StorageKey,Sha256,HttpStatus,ContentType,SchemaVersion FROM SourceSnapshots ORDER BY Id'
    $groups.issueHistory=Rows 'SELECT Id,CrawlRunId,SourceUrl,Stage,Code,Message FROM ImportIssues ORDER BY Id'
    $groups.documentFields=Rows 'SELECT l.* FROM LegalDocuments l JOIN SourceRecords s ON s.ContentId=l.ContentId WHERE s.Source=N''qldd.mae.gov.vn'' ORDER BY l.ContentId'
    $groups.draftFields=Rows 'SELECT d.* FROM DraftDocuments d JOIN SourceRecords s ON s.ContentId=d.ContentId WHERE s.Source=N''qldd.mae.gov.vn'' ORDER BY d.ContentId'
    $mediaRoot=LocalRoot 'Storage__MediaRoot';$snapshotRoot=LocalRoot 'Storage__SnapshotRoot'
    $groups.mediaFiles=@($groups.media | ForEach-Object {FileEntry $mediaRoot $_.StorageKey $_.Sha256})
    $groups.snapshotFiles=@($groups.snapshots | ForEach-Object {FileEntry $snapshotRoot $_.StorageKey $_.Sha256})
    $sample=Get-Content -LiteralPath (Join-Path $snapshotRoot 'sample-manifest.json') -Encoding UTF8 -Raw | ConvertFrom-Json
    $groups.manifestSnapshotFiles=@($sample.Snapshots | ForEach-Object {FileEntry $snapshotRoot $_.StorageKey $_.Sha256})
    $reportPath=Join-Path $script:ProjectRoot 'docs/evidence/source-report.json';$report=Get-Content -LiteralPath $reportPath -Encoding UTF8 -Raw | ConvertFrom-Json
    $groups.exceptionLedger=@($report.Issues.Details | Where-Object {-not $_.Resolved});$groups.sourceReportFile=@(FileEntry (Split-Path $reportPath) 'source-report.json' (Get-FileHash -LiteralPath $reportPath -Algorithm SHA256).Hash.ToLowerInvariant())
    $groupHashes=[ordered]@{};foreach($name in $groups.Keys){$groupHashes[$name]=[ordered]@{count=@($groups[$name]).Count;sha256=HashText (ConvertTo-Json -InputObject $groups[$name] -Depth 30 -Compress)}}
    $counts=Rows 'SELECT (SELECT COUNT(*) FROM Contents) AS Contents,(SELECT COUNT(*) FROM SourceRecords WHERE Source=N''qldd.mae.gov.vn'') AS SourceRecords,(SELECT COUNT(*) FROM Revisions) AS Revisions,(SELECT COUNT(*) FROM SourceUrlAliases) AS Aliases,(SELECT COUNT(*) FROM MediaAssets) AS MediaAssets,(SELECT COUNT(*) FROM MediaAssets WHERE MimeType LIKE N''image/%'') AS Images,(SELECT COUNT(*) FROM MediaAssets WHERE MimeType=N''application/pdf'') AS Pdfs,(SELECT COUNT(*) FROM SourceSnapshots) AS Snapshots,(SELECT COUNT(*) FROM Contents WHERE Kind=5) AS VideoMetadata,(SELECT COUNT(*) FROM MediaAssets WHERE MimeType LIKE N''video/%'') AS VideoFiles'
    $comparisons=@();if($CompareTo){$old=Get-Content -LiteralPath (Join-Path $script:ProjectRoot $CompareTo) -Encoding UTF8 -Raw | ConvertFrom-Json;foreach($name in $groups.Keys){$previous=$old.groupHashes.$name;$comparisons+= [ordered]@{group=$name;beforeCount=$previous.count;afterCount=$groupHashes[$name].count;equal=($previous.sha256 -ceq $groupHashes[$name].sha256)}}}
    $result=[ordered]@{schemaVersion=1;utc=[DateTimeOffset]::UtcNow.ToString('O');database=$Database;target=$target;counts=$counts[0];manifestSnapshotCount=@($sample.Snapshots).Count;distinctManifestSnapshotUrlHashCount=@($sample.Snapshots|Select-Object Url,Sha256 -Unique).Count;exceptionDistinctCount=@($groups.exceptionLedger | Select-Object SourceUrl,Code -Unique).Count;groups=$groups;groupHashes=$groupHashes;comparisons=$comparisons}
    $destination=[IO.Path]::GetFullPath((Join-Path $script:ProjectRoot $Output));if(-not $destination.StartsWith((Join-Path $script:ProjectRoot '.local')+'\',[StringComparison]::OrdinalIgnoreCase)){throw 'Evidence must remain private in project .local.'};[IO.Directory]::CreateDirectory((Split-Path $destination))|Out-Null;[IO.File]::WriteAllText($destination,(ConvertTo-Json -InputObject $result -Depth 40),[Text.UTF8Encoding]::new($false))
    Write-Output ('Preservation '+$Database+': '+(ConvertTo-Json -InputObject $counts[0] -Compress));Write-Output ('Missing/mismatched media='+@($groups.mediaFiles|Where-Object {-not $_.matches}).Count+' SQL snapshots='+@($groups.snapshotFiles|Where-Object {-not $_.matches}).Count+' manifestSnapshots='+$result.manifestSnapshotCount+' uniqueUrlHash='+$result.distinctManifestSnapshotUrlHashCount+' mismatched='+@($groups.manifestSnapshotFiles|Where-Object {-not $_.matches}).Count+'; distinct unresolved exceptions='+$result.exceptionDistinctCount)
    if($CompareTo){$bad=@($comparisons|Where-Object {-not $_.equal});Write-Output ('Comparison mismatches='+$bad.Count+'; '+(@($bad|ForEach-Object {$_.group}) -join ','));if($bad.Count){exit 2}}
} finally { $conn.Dispose() }
